<?php
namespace Modules\BankingCoreDeposits\Http\Controllers;
use Illuminate\Routing\Controller; use Modules\BankingCoreDeposits\Entities\DepositAccount; use Modules\BankingCoreDeposits\Entities\DepositTransaction; use Modules\BankingCoreDeposits\Entities\FixedDeposit;
class ReportController extends Controller { public function depositRegister(){ $rows=DepositAccount::latest()->paginate(50); return view('bankingcoredeposits::reports.deposit-register',compact('rows')); } public function newAccounts(){ $rows=DepositAccount::whereDate('created_at','>=',request('from',now()->startOfMonth()))->paginate(50); return view('bankingcoredeposits::reports.simple',compact('rows')); } public function closedAccounts(){ $rows=DepositAccount::where('status','closed')->paginate(50); return view('bankingcoredeposits::reports.simple',compact('rows')); } public function dormantAccounts(){ $rows=DepositAccount::where('status','dormant')->paginate(50); return view('bankingcoredeposits::reports.simple',compact('rows')); } public function interestAccrual(){ return view('bankingcoredeposits::reports.interest-accrual'); } public function maturityRegister(){ $rows=FixedDeposit::orderBy('maturity_date')->paginate(50); return view('bankingcoredeposits::reports.maturity-register',compact('rows')); } public function tellerSummary(){ $rows=DepositTransaction::latest()->paginate(50); return view('bankingcoredeposits::reports.teller-summary',compact('rows')); } }
